     5  #include "prep.h"
     6
     7  // prep - Control Value Program
     8  // http://www.microsoft.com/typography/otspec/prep.htm
     9
    10  namespace ots {
    11
    12  bool OpenTypePREP::Parse(const uint8_t *data, size_t length) {
    13    Buffer table(data, length);
    14
    15    if (length >= 128 * 1024u) {
    16      return Error("table length %ld > 120K", length);  // almost all prep tables are less than 9k bytes.
    17    }
    18
    19    if (!table.Skip(length)) {
    20      return Error("Failed to read table of length %ld", length);
    21    }
    22
    23    this->m_data = data;
    24    this->m_length = length;
    25    return true;
    26  }
    27
    28  bool OpenTypePREP::Serialize(OTSStream *out) {
    29    if (!out->Write(this->m_data, this->m_length)) {
    30      return Error("Failed to write table length");
    31    }
    32
    33    return true;
    34  }
    35
    36  bool OpenTypePREP::ShouldSerialize() {
    37    return Table::ShouldSerialize() &&
    38           // this table is not for CFF fonts.
    39           GetFont()->GetTable(OTS_TAG_GLYF) != NULL;
    40  }
    41
    42  }  // namespace ots
