    10  namespace ots {
    11
    12  bool OpenTypeCVT::Parse(const uint8_t *data, size_t length) {
    13    Buffer table(data, length);
    14
    15    if (length >= 128 * 1024u) {
    16      return Error("Length (%d) > 120K");  // almost all cvt tables are less than 4k bytes.
    17    }
    18
    19    if (length % 2 != 0) {
    20      return Error("Uneven cvt length (%d)", length);
    21    }
    22
    23    if (!table.Skip(length)) {
    24      return Error("Length too high");
    25    }
    26
    27    this->data = data;
    28    this->length = length;
    29    return true;
    30  }
    31
    32  bool OpenTypeCVT::Serialize(OTSStream *out) {
    33    if (!out->Write(this->data, this->length)) {
    34      return Error("Failed to write cvt table");
    35    }
    36
    37    return true;
    38  }
