    31  namespace ots {
    32
    33  bool OpenTypeGDEF::ParseAttachListTable(const uint8_t *data, size_t length) {
    34    ots::Buffer subtable(data, length);
    35
    36    uint16_t offset_coverage = 0;
    37    uint16_t glyph_count = 0;
    38    if (!subtable.ReadU16(&offset_coverage) ||
    39        !subtable.ReadU16(&glyph_count)) {
    40      return Error("Failed to read gdef header");
    41    }
    42    const unsigned attach_points_end =
    43        2 * static_cast<unsigned>(glyph_count) + 4;
    44    if (attach_points_end > std::numeric_limits<uint16_t>::max()) {
    45      return Error("Bad glyph count in gdef");
    46    }
    47    if (offset_coverage == 0 || offset_coverage >= length ||
    48        offset_coverage < attach_points_end) {
    49      return Error("Bad coverage offset %d", offset_coverage);
    50    }
    51    if (glyph_count > this->m_num_glyphs) {
    52      return Error("Bad glyph count %u", glyph_count);
    53    }
    54
    55    std::vector<uint16_t> attach_points;
    56    attach_points.resize(glyph_count);
    57    for (unsigned i = 0; i < glyph_count; ++i) {
    58      if (!subtable.ReadU16(&attach_points[i])) {
    59        return Error("Can't read attachment point %d", i);
    60      }
    61      if (attach_points[i] >= length ||
    62          attach_points[i] < attach_points_end) {
    63        return Error("Bad attachment point %d of %d", i, attach_points[i]);
    64      }
    65    }
    66
    67    // Parse coverage table
    68    if (!ots::ParseCoverageTable(GetFont(), data + offset_coverage,
    69                                 length - offset_coverage, this->m_num_glyphs)) {
    70      return Error("Bad coverage table");
    71    }
    72
    73    // Parse attach point table
    74    for (unsigned i = 0; i < attach_points.size(); ++i) {
    75      subtable.set_offset(attach_points[i]);
    76      uint16_t point_count = 0;
    77      if (!subtable.ReadU16(&point_count)) {
    78        return Error("Can't read point count %d", i);
    79      }
    80      if (point_count == 0) {
    81        return Error("zero point count %d", i);
    82      }
    83      uint16_t last_point_index = 0;
    84      uint16_t point_index = 0;
    85      for (unsigned j = 0; j < point_count; ++j) {
    86        if (!subtable.ReadU16(&point_index)) {
    87          return Error("Can't read point index %d in point %d", j, i);
    88        }
    89        // Contour point indeces are in increasing numerical order
    90        if (last_point_index != 0 && last_point_index >= point_index) {
    91          return Error("bad contour indeces: %u >= %u",
    92                      last_point_index, point_index);
    93        }
    94        last_point_index = point_index;
    95      }
    96    }
    97    return true;
    98  }
