    71  // Lookup Type 1:
    72  // Single Substitution Subtable
    73  bool ParseSingleSubstitution(const ots::Font *font,
    74                               const uint8_t *data, const size_t length) {
    75    ots::Buffer subtable(data, length);
    76
    77    uint16_t format = 0;
    78    uint16_t offset_coverage = 0;
    79
    80    if (!subtable.ReadU16(&format) ||
    81        !subtable.ReadU16(&offset_coverage)) {
    82      return OTS_FAILURE_MSG("Failed to read single subst table header");
    83    }
    84
    85    ots::OpenTypeMAXP *maxp = dynamic_cast<ots::OpenTypeMAXP*>(
    86        font->GetTable(OTS_TAG_MAXP));
    87    if (!maxp) {
    88      return OTS_FAILURE_MSG("Required maxp table missing");
    89    }
    90    const uint16_t num_glyphs = maxp->num_glyphs;
    91    if (format == 1) {
    92      // Parse SingleSubstFormat1
    93      int16_t delta_glyph_id = 0;
    94      if (!subtable.ReadS16(&delta_glyph_id)) {
    95        return OTS_FAILURE_MSG("Failed to read glyph shift from format 1 single subst table");
    96      }
    97      if (std::abs(delta_glyph_id) >= num_glyphs) {
    98        return OTS_FAILURE_MSG("bad glyph shift of %d in format 1 single subst table", delta_glyph_id);
    99      }
   100    } else if (format == 2) {
   101      // Parse SingleSubstFormat2
   102      uint16_t glyph_count = 0;
   103      if (!subtable.ReadU16(&glyph_count)) {
   104        return OTS_FAILURE_MSG("Failed to read glyph cound in format 2 single subst table");
   105      }
   106      if (glyph_count > num_glyphs) {
   107        return OTS_FAILURE_MSG("Bad glyph count %d > %d in format 2 single subst table", glyph_count, num_glyphs);
   108      }
   109      for (unsigned i = 0; i < glyph_count; ++i) {
   110        uint16_t substitute = 0;
   111        if (!subtable.ReadU16(&substitute)) {
   112          return OTS_FAILURE_MSG("Failed to read substitution %d in format 2 single subst table", i);
   113        }
   114        if (substitute >= num_glyphs) {
   115          return OTS_FAILURE_MSG("too large substitute: %u", substitute);
   116        }
   117      }
   118    } else {
   119      return OTS_FAILURE_MSG("Bad single subst table format %d", format);
   120    }
