    42  bool ReadOffset(ots::Buffer *table, uint8_t off_size, uint32_t *offset) {
    43    if (off_size > 4) {
    44      return OTS_FAILURE();
    45    }
    46
    47    uint32_t tmp32 = 0;
    48    for (unsigned i = 0; i < off_size; ++i) {
    49      uint8_t tmp8 = 0;
    50      if (!table->ReadU8(&tmp8)) {
    51        return OTS_FAILURE();
    52      }
    53      tmp32 <<= 8;
    54      tmp32 += tmp8;
    55    }
    56    *offset = tmp32;
    57    return true;
    58  }
