     9  // head - Font Header
    10  // http://www.microsoft.com/typography/otspec/head.htm
    11
    12  namespace ots {
    13
    14  bool OpenTypeHEAD::Parse(const uint8_t *data, size_t length) {
    15    Buffer table(data, length);
    16
    17    uint32_t version = 0;
    18    if (!table.ReadU32(&version) ||
    19        !table.ReadU32(&this->revision)) {
    20      return Error("Failed to read head header");
    21    }
    22
    23    if (version >> 16 != 1) {
    24      return Error("Bad head table version of %d", version);
    25    }
    26
    27    // Skip the checksum adjustment
    28    if (!table.Skip(4)) {
    29      return Error("Failed to read checksum");
    30    }
    31
    32    uint32_t magic;
    33    if (!table.ReadU32(&magic) || magic != 0x5F0F3CF5) {
    34      return Error("Failed to read font magic number");
    35    }
    36
    37    if (!table.ReadU16(&this->flags)) {
    38      return Error("Failed to read head flags");
    39    }
    40
    41    // We allow bits 0..4, 11..13
    42    this->flags &= 0x381f;
    43
    44    if (!table.ReadU16(&this->ppem)) {
    45      return Error("Failed to read pixels per em");
    46    }
    47
    48    // ppem must be in range
    49    if (this->ppem < 16 ||
    50        this->ppem > 16384) {
    51      return Error("Bad ppm of %d", this->ppem);
    52    }
    53
    54    // ppem must be a power of two
    55  #if 0
    56    // We don't call ots_failure() for now since lots of TrueType fonts are
    57    // not following this rule. Putting a warning here is too noisy.
    58    if ((this->ppem - 1) & this->ppem) {
    59      return Error("ppm not a power of two: %d", this->ppem);
    60    }
    61  #endif
    62
    63    if (!table.ReadR64(&this->created) ||
    64        !table.ReadR64(&this->modified)) {
    65      return Error("Can't read font dates");
    66    }
    67
    68    if (!table.ReadS16(&this->xmin) ||
    69        !table.ReadS16(&this->ymin) ||
    70        !table.ReadS16(&this->xmax) ||
    71        !table.ReadS16(&this->ymax)) {
    72      return Error("Failed to read font bounding box");
    73    }
    74
    75    if (this->xmin > this->xmax) {
    76      return Error("Bad x dimension in the font bounding box (%d, %d)", this->xmin, this->xmax);
    77    }
    78    if (this->ymin > this->ymax) {
    79      return Error("Bad y dimension in the font bounding box (%d, %d)", this->ymin, this->ymax);
    80    }
    81
    82    if (!table.ReadU16(&this->mac_style)) {
    83      return Error("Failed to read font style");
    84    }
    85
    86    // We allow bits 0..6
    87    this->mac_style &= 0x7f;
    88
    89    if (!table.ReadU16(&this->min_ppem)) {
    90      return Error("Failed to read font minimum ppm");
    91    }
    92
    93    // We don't care about the font direction hint
    94    if (!table.Skip(2)) {
    95      return Error("Failed to skip font direction hint");
    96    }
    97
    98    if (!table.ReadS16(&this->index_to_loc_format)) {
    99      return Error("Failed to read index to loc format");
   100    }
   101    if (this->index_to_loc_format < 0 ||
   102        this->index_to_loc_format > 1) {
   103      return Error("Bad index to loc format %d", this->index_to_loc_format);
   104    }
   105
   106    int16_t glyph_data_format;
   107    if (!table.ReadS16(&glyph_data_format) ||
   108        glyph_data_format) {
   109      return Error("Failed to read glyph data format");
   110    }
   111
   112    return true;
   113  }
