   115  bool OpenTypeHEAD::Serialize(OTSStream *out) {
   116    if (!out->WriteU32(0x00010000) ||
   117        !out->WriteU32(this->revision) ||
   118        !out->WriteU32(0) ||  // check sum not filled in yet
   119        !out->WriteU32(0x5F0F3CF5) ||
   120        !out->WriteU16(this->flags) ||
