   214  bool ProcessTTC(ots::FontFile *header,
   215                  ots::OTSStream *output,
   216                  const uint8_t *data,
   217                  size_t length,
   218                  uint32_t index) {
   219    ots::Buffer file(data, length);
   220
   221    // we disallow all files > 1GB in size for sanity.
   222    if (length > 1024 * 1024 * 1024) {
   223      return OTS_FAILURE_MSG_HDR("file exceeds 1GB");
   224    }
   225
   226    uint32_t ttc_tag;
   227    if (!file.ReadU32(&ttc_tag)) {
   228      return OTS_FAILURE_MSG_HDR("Error reading TTC tag");
   229    }
   230    if (ttc_tag != OTS_TAG('t','t','c','f')) {
   231      return OTS_FAILURE_MSG_HDR("Invalid TTC tag");
   232    }
   233
   234    uint32_t ttc_version;
   235    if (!file.ReadU32(&ttc_version)) {
   236      return OTS_FAILURE_MSG_HDR("Error reading TTC version");
   237    }
   238    if (ttc_version != 0x00010000 && ttc_version != 0x00020000) {
   239      return OTS_FAILURE_MSG_HDR("Invalid TTC version");
   240    }
   241
   242    uint32_t num_fonts;
   243    if (!file.ReadU32(&num_fonts)) {
   244      return OTS_FAILURE_MSG_HDR("Error reading number of TTC fonts");
   245    }
   246    // Limit the allowed number of subfonts to have same memory allocation.
   247    if (num_fonts > 0x10000) {
   248      return OTS_FAILURE_MSG_HDR("Too many fonts in TTC");
   249    }
   250
   251    std::vector<uint32_t> offsets(num_fonts);
   252    for (unsigned i = 0; i < num_fonts; i++) {
   253      if (!file.ReadU32(&offsets[i])) {
   254        return OTS_FAILURE_MSG_HDR("Error reading offset to OffsetTable");
   255      }
   256    }
   257
   258    if (ttc_version == 0x00020000) {
   259      // We don't care about these fields of the header:
   260      // uint32_t dsig_tag, dsig_length, dsig_offset
   261      if (!file.Skip(3 * 4)) {
   262        return OTS_FAILURE_MSG_HDR("Error reading DSIG offset and length in TTC font");
   263      }
   264    }
   265
   266    if (index == static_cast<uint32_t>(-1)) {
   267      if (!output->WriteU32(ttc_tag) ||
   268          !output->WriteU32(0x00010000) ||
   269          !output->WriteU32(num_fonts) ||
   270          !output->Seek((3 + num_fonts) * 4)) {
   271        return OTS_FAILURE_MSG_HDR("Error writing output");
   272      }
   273
   274      // Keep references to the fonts processed in the loop below, as we need
   275      // them for reused tables.
   276      std::vector<ots::Font> fonts(num_fonts, ots::Font(header));
   277
   278      for (unsigned i = 0; i < num_fonts; i++) {
   279        uint32_t out_offset = output->Tell();
   280        if (!output->Seek((3 + i) * 4) ||
   281            !output->WriteU32(out_offset) ||
   282            !output->Seek(out_offset)) {
   283          return OTS_FAILURE_MSG_HDR("Error writing output");
   284        }
   285        if (!ProcessTTF(header, &fonts[i], output, data, length, offsets[i])) {
   286          return false;
   287        }
   288      }
   289
   290      return true;
   291    } else {
   292      if (index >= num_fonts) {
   293        return OTS_FAILURE_MSG_HDR("Requested font index is bigger than the number of fonts in the TTC file");
   294      }
   295
   296      ots::Font font(header);
   297      return ProcessTTF(header, &font, output, data, length, offsets[index]);
   298    }
   299  }
   300
   301  bool ProcessWOFF(ots::FontFile *header,
   302                   ots::Font *font,
   303                   ots::OTSStream *output, const uint8_t *data, size_t length) {
   304    ots::Buffer file(data, length);
   305
   306    // we disallow all files > 1GB in size for sanity.
   307    if (length > 1024 * 1024 * 1024) {
   308      return OTS_FAILURE_MSG_HDR("file exceeds 1GB");
   309    }
   310
   311    uint32_t woff_tag;
   312    if (!file.ReadU32(&woff_tag)) {
   313      return OTS_FAILURE_MSG_HDR("error reading WOFF marker");
   314    }
   315
   316    if (woff_tag != OTS_TAG('w','O','F','F')) {
   317      return OTS_FAILURE_MSG_HDR("invalid WOFF marker");
   318    }
   319
   320    if (!file.ReadU32(&font->version)) {
   321      return OTS_FAILURE_MSG_HDR("error reading version tag");
   322    }
   323    if (!ots::IsValidVersionTag(font->version)) {
   324      return OTS_FAILURE_MSG_HDR("invalid version tag");
   325    }
   326
   327    uint32_t reported_length;
   328    if (!file.ReadU32(&reported_length) || length != reported_length) {
   329      return OTS_FAILURE_MSG_HDR("incorrect file size in WOFF header");
   330    }

330    }
   331
   332    if (!file.ReadU16(&font->num_tables) || !font->num_tables) {
   333      return OTS_FAILURE_MSG_HDR("error reading number of tables");
   334    }
   335
   336    uint16_t reserved_value;
   337    if (!file.ReadU16(&reserved_value) || reserved_value) {
   338      return OTS_FAILURE_MSG_HDR("error in reserved field of WOFF header");
   339    }
   340
   341    uint32_t reported_total_sfnt_size;
   342    if (!file.ReadU32(&reported_total_sfnt_size)) {
   343      return OTS_FAILURE_MSG_HDR("error reading total sfnt size");
   344    }
   345
   346    // We don't care about these fields of the header:
   347    //   uint16_t major_version, minor_version
   348    if (!file.Skip(2 * 2)) {
   349      return OTS_FAILURE_MSG_HDR("Failed to read 'majorVersion' or 'minorVersion'");
   350    }
   351
   352    // Checks metadata block size.
   353    uint32_t meta_offset;
   354    uint32_t meta_length;
   355    uint32_t meta_length_orig;
   356    if (!file.ReadU32(&meta_offset) ||
   357        !file.ReadU32(&meta_length) ||
   358        !file.ReadU32(&meta_length_orig)) {
   359      return OTS_FAILURE_MSG_HDR("Failed to read header metadata block fields");
   360    }
   361    if (meta_offset) {
   362      if (meta_offset >= length || length - meta_offset < meta_length) {
   363        return OTS_FAILURE_MSG_HDR("Invalid metadata block offset or length");
   364      }
   365    }
   366
   367    // Checks private data block size.
   368    uint32_t priv_offset;
   369    uint32_t priv_length;
   370    if (!file.ReadU32(&priv_offset) ||
   371        !file.ReadU32(&priv_length)) {
   372      return OTS_FAILURE_MSG_HDR("Failed to read header private block fields");
   373    }
   374    if (priv_offset) {
   375      if (priv_offset >= length || length - priv_offset < priv_length) {
   376        return OTS_FAILURE_MSG_HDR("Invalid private block offset or length");
   377      }
   378    }
   379
   380    // Next up is the list of tables.
   381    std::vector<ots::TableEntry> tables;
   382
   383    uint32_t first_index = 0;
   384    uint32_t last_index = 0;
   385    // Size of sfnt header plus size of table records.
   386    uint64_t total_sfnt_size = 12 + 16 * font->num_tables;
   387    for (unsigned i = 0; i < font->num_tables; ++i) {
   388      ots::TableEntry table;
   389      if (!file.ReadU32(&table.tag) ||
   390          !file.ReadU32(&table.offset) ||
   391          !file.ReadU32(&table.length) ||
   392          !file.ReadU32(&table.uncompressed_length) ||
   393          !file.ReadU32(&table.chksum)) {
   394        return OTS_FAILURE_MSG_HDR("error reading table directory");
   395      }
   396
   397      total_sfnt_size += ots::Round4(table.uncompressed_length);
   398      if (total_sfnt_size > std::numeric_limits<uint32_t>::max()) {
   399        return OTS_FAILURE_MSG_HDR("sfnt size overflow");
   400      }
   401      tables.push_back(table);
   402      if (i == 0 || tables[first_index].offset > table.offset)
   403        first_index = i;
   404      if (i == 0 || tables[last_index].offset < table.offset)
   405        last_index = i;
   406    }
   407
   408    if (reported_total_sfnt_size != total_sfnt_size) {
   409      return OTS_FAILURE_MSG_HDR("uncompressed sfnt size mismatch");
   410    }
   411
   412    // Table data must follow immediately after the header.
   413    if (tables[first_index].offset != ots::Round4(file.offset())) {
   414      return OTS_FAILURE_MSG_HDR("junk before tables in WOFF file");
   415    }
   416
   417    if (tables[last_index].offset >= length ||
   418        length - tables[last_index].offset < tables[last_index].length) {
   419      return OTS_FAILURE_MSG_HDR("invalid table location/size");
   420    }
   421    // Blocks must follow immediately after the previous block.
   422    // (Except for padding with a maximum of three null bytes)
   423    uint64_t block_end = ots::Round4(
   424        static_cast<uint64_t>(tables[last_index].offset) +
   425        static_cast<uint64_t>(tables[last_index].length));
   426    if (block_end > std::numeric_limits<uint32_t>::max()) {
   427      return OTS_FAILURE_MSG_HDR("invalid table location/size");
   428    }
   429    if (meta_offset) {
   430      if (block_end != meta_offset) {
   431        return OTS_FAILURE_MSG_HDR("Invalid metadata block offset");
   432      }
   433      block_end = ots::Round4(static_cast<uint64_t>(meta_offset) +
   434                              static_cast<uint64_t>(meta_length));
   435      if (block_end > std::numeric_limits<uint32_t>::max()) {
   436        return OTS_FAILURE_MSG_HDR("Invalid metadata block length");
   437      }
   438    }
   439    if (priv_offset) {
   440      if (block_end != priv_offset) {
   441        return OTS_FAILURE_MSG_HDR("Invalid private block offset");
   442      }
   443      block_end = ots::Round4(static_cast<uint64_t>(priv_offset) +
   444                              static_cast<uint64_t>(priv_length));
   445      if (block_end > std::numeric_limits<uint32_t>::max()) {
   446        return OTS_FAILURE_MSG_HDR("Invalid private block length");
   447      }
   448    }
   449    if (block_end != ots::Round4(length)) {
   450      return OTS_FAILURE_MSG_HDR("File length mismatch (trailing junk?)");
   451    }
   452
   453    return ProcessGeneric(header, font, woff_tag, output, data, length, tables, file);
   454  }
